INSERT INTO data_dictionary_fields (id, dataset, sort, field_name, definition, value_style) VALUES ('d20d0d31-947a-4370-8c6a-e9cb4eafcede', (SELECT id FROM dataset_metadata WHERE source_collection='disbursement' LIMIT 1), 1, 'Date', 'The date the disbursement occurred.', 'rows');
INSERT INTO data_dictionary_fields (id, dataset, sort, field_name, definition, value_style) VALUES ('1f3972e9-e034-4880-84a1-fc3f61533ae3', (SELECT id FROM dataset_metadata WHERE source_collection='disbursement' LIMIT 1), 2, 'Fund Type', 'The type of recipient receiving the disbursement.', 'rows');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('756f7e64-04b2-47f3-b4fd-2f6fedf02ed2', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 1, 'BLM–Nat Petrol Reserve–2', 'Funds from oil and gas leases directed to the National Petroleum Reserve in Alaska.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('86da36fa-8fec-4a03-b74c-9898f21f0ce2', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 2, 'Bureau of Land Management', 'Certain funds are directed back to the federal agencies that administer these lands and waters. These funds help cover the agencies'' operational costs.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('cd4e6939-8ff6-4c08-aa21-d04489b1d652', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 3, 'Bureau of Ocean Energy Management', 'Certain funds are directed back to the federal agencies that administer these lands and waters. These funds help cover the agencies'' operational costs.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('3e7d7252-4acb-45ec-b8c4-ad43832e2f61', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 4, 'Bureau of Safety & Environmental Enforcement', 'Certain funds are directed back to the federal agencies that administer these lands and waters. These funds help cover the agencies'' operational costs.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('a3aa71a6-5ba0-48a4-bf41-011dfe2c3325', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 5, 'Fish & Wildlife', 'Certain funds are directed back to the federal agencies that administer these lands and waters. These funds help cover the agencies'' operational costs.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('4e2c71ee-c805-4dd6-a222-003835ece776', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 6, 'Forest Service', 'Certain funds are directed back to the federal agencies that administer these lands and waters. These funds help cover the agencies'' operational costs.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('ff3b23d0-19ca-4426-9555-04af970db3a2', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 7, 'Land & Water Conservation Fund (LWCF)', 'This fund provides matching grants to states and local governments. Using these grants, governments buy and develop public outdoor recreation areas across the 50 states.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('d3555863-dc32-4667-aee2-f2cf0bbaa432', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 8, 'Land and Water Conservation Fund GOMESA', 'The Gulf of Mexico Energy Security Act (GOMESA) (Gulf of America) of 2006 specifies that 12.5% of revenues from certain Gulf of America leases be directed to the LWCF stateside program. States can receive up to $125 million a year in funding. This portion of LWCF funds is not subject to the congressional appropriation process. Otherwise, they are treated similarly to regular LWCF funds.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('1b134fee-e8bb-4082-a2d8-af8ebaf2f18d', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 9, 'Lease Process Improvement (BLM)', 'This fund was established to support the coordination and processing of oil and gas leases on federal onshore land.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('ea2832ba-406e-400b-a10a-1293ae945c2b', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 10, 'Native American Tribes & Allottees', 'ONRR disburses 100% of revenue collected from resource extraction on Native American lands back to Native American tribes, nations, and individual Indian landowners.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('8656f6ab-7d3c-4006-b158-08e90ddd3cb2', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 11, 'Reclamation Fund', 'Established by Congress in 1902. Funds the development of irrigation projects on arid and semiarid lands of the 17 western states.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('2ac768ce-dacf-48e7-a7e5-5bc16afda9a2', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 12, 'State', 'Funds disbursed to states fall under the jurisdiction of each state. Each state determines how the funds will be used.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('3ca7a2db-e94a-4d34-ad22-0cffc0f928da', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 13, 'State 8(g)', '27% of revenue from leases in the 8(g) Zone are shared with states. The 8(g) Zone is the first three nautical miles of the Outer Continental Shelf.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('193e0077-b739-4430-bb5d-444e1d9ee45b', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 14, 'State GOMESA', '37.5% of revenue from certain leases in the Gulf of America are shared with Alabama, Louisiana, Mississippi, and Texas.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('f29624af-f5fe-4d22-a23a-bff2e24a327b', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 15, 'U.S. Treasury', 'Funds disbursed to the Treasury go to the General Fund, which is the federal government''s basic operating fund. The General Fund pays for roughly two-thirds of all federal expenditures, including the U.S. military, national parks, and schools.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('99a46685-f7ec-413b-860e-6f9eda92ea29', '1f3972e9-e034-4880-84a1-fc3f61533ae3', 16, 'U.S. Treasury GOMESA', 'The Gulf of Mexico Energy Security Act (GOMESA) (Gulf of America) of 2006 specifies that 50% of revenues from certain Gulf of America leases be directed to the U.S. Treasury.');
INSERT INTO data_dictionary_fields (id, dataset, sort, field_name, definition, value_style) VALUES ('e54646c4-0e6b-464a-b2e3-374f94b3e674', (SELECT id FROM dataset_metadata WHERE source_collection='disbursement' LIMIT 1), 3, 'Land Category', 'Whether the origin of the revenue being disbursed is offshore or onshore.', 'rows');
INSERT INTO data_dictionary_fields (id, dataset, sort, field_name, definition, value_style) VALUES ('1741d4c1-2c6c-4561-ae11-0069ceb852b1', (SELECT id FROM dataset_metadata WHERE source_collection='disbursement' LIMIT 1), 4, 'Disbursement Type', 'Disbursement types are guided by revenue-sharing legislation and agreements. For example, GOMESA and 8(g) direct portions of offshore revenue to states, local governments, and designated funds. Disbursements from the production of geothermal energy is also shared with county governments.', 'rows');
INSERT INTO data_dictionary_fields (id, dataset, sort, field_name, definition, value_style) VALUES ('56958b1f-bf35-4699-8aef-112734e41d58', (SELECT id FROM dataset_metadata WHERE source_collection='disbursement' LIMIT 1), 5, 'State', 'The state that received the disbursement in accordance with revenue-sharing legislation.', 'rows');
INSERT INTO data_dictionary_fields (id, dataset, sort, field_name, definition, value_style) VALUES ('d976c532-fda7-40cf-ac9f-3c7bf093b990', (SELECT id FROM dataset_metadata WHERE source_collection='disbursement' LIMIT 1), 6, 'County', 'The county, parish, or borough that received the disbursement in accordance with revenue-sharing legislation.', 'rows');
INSERT INTO data_dictionary_fields (id, dataset, sort, field_name, definition, value_style) VALUES ('44a1dcbf-eeef-4869-b345-c8abd3260cd8', (SELECT id FROM dataset_metadata WHERE source_collection='disbursement' LIMIT 1), 7, 'Category (dollar)', 'Includes the phases of lease payments.', 'rows');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('1c3e7f3d-a1b9-49b6-970c-6a54a7db3b2b', '44a1dcbf-eeef-4869-b345-c8abd3260cd8', 1, 'Bonuses', 'The amount paid by the highest bidder for a natural resource lease.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('0bb9a194-1d4b-4289-b642-eb28c4d99976', '44a1dcbf-eeef-4869-b345-c8abd3260cd8', 2, 'Rents', 'The annual payment for leasing lands or waters before production starts.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('9c529d9c-d047-4a67-8d84-831e23d96214', '44a1dcbf-eeef-4869-b345-c8abd3260cd8', 3, 'Royalties', 'Payments for extracted natural resources, determined by a percentage of the resources'' production value.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('f033003b-a675-4fc0-8c65-b4461bc06f83', '44a1dcbf-eeef-4869-b345-c8abd3260cd8', 4, 'Other Distributions', 'Revenues from fees and civil penalties.');
INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('fc676306-03f7-47c2-955c-94396ac43efb', '44a1dcbf-eeef-4869-b345-c8abd3260cd8', 5, 'Sequestration', 'This represents statutory spending limits which are withheld from certain government programs. Some program funds are returned in following fiscal year.');
INSERT INTO data_dictionary_fields (id, dataset, sort, field_name, definition, value_style) VALUES ('a2d82853-5236-4b7a-b923-caa2af4ca206', (SELECT id FROM dataset_metadata WHERE source_collection='disbursement' LIMIT 1), 8, 'Commodity', 'Refers to the commodity that generated the revenue. For oil and gas, the commodity listed depends on the phase of production. Since it''s unknown whether a lease will produce oil, gas, or both, the two commodities are combined in the bonus and rent phases and listed as "Oil & Gas (pre-production)."', 'tags');
