INSERT INTO data_dictionary_values (id, field, sort, term, definition) VALUES ('1668e2b7-07c9-4d3f-a40c-052c15590966', 'a2d82853-5236-4b7a-b923-caa2af4ca206', 2, 'Coal', NULL);
