-- seed-disbursements-dictionary.sql — data_dictionary content for the Monthly
-- disbursements dataset (from the dataset-page mockup DICT). Idempotent-ish: run
-- the DELETE first to re-seed. Resolves the dataset by source_collection so it's
-- portable across instances. Run: psql "$DB_URL" -f this-file.sql
BEGIN;
-- clear any existing dictionary for this dataset first (cascades to values via FK).
DELETE FROM data_dictionary_fields WHERE dataset = (SELECT id FROM dataset_metadata WHERE source_collection='disbursement' LIMIT 1);
COMMIT;
